// EA12.5.1 Describe the importance of minerals and mineral exploration at the local, provincial, national and global levels
// Source: June 2006 public exam, item 45.
E("es-u5-51-q01",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which is directly associated with hydrothermal activity?","native copper",["crude oil","placer gold","rock gypsum"],"Hydrothermal activity, hot mineral-rich water moving through cracks in rock, deposits native copper as the fluids cool and the metal precipitates out of solution.",{});}]),["Hot water moving through rock carries dissolved metals."]);

// Source: June 2006 public exam, item 46.
E("es-u5-51-q02",5,["EA12.5.1"],1,"var",varset([function(){return mcq("What property of gold enables it to form placer deposits?","high density",["high hardness value","low density","low hardness value"],"Gold is far denser than the sediment around it, so running water cannot carry it far; it settles out of the current and concentrates in placer deposits where the water slows.",{});}]),["Think about why gold sinks while sand is carried away."]);

// Source: June 2006 public exam, item 49.
E("es-u5-51-q03",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which mineral is correctly matched with its economic use?","barite: drilling mud",["galena: cement","pyrite: copper wire","sphalerite: lead pipe"],"Barite is a dense mineral that is ground up and added to drilling mud to increase its weight. Galena is the ore of lead, pyrite is an iron sulfide, and sphalerite is the ore of zinc, so none of those pairings is correct.",{});}]),["One mineral is named for its use in drilling."]);

// Source: June 2007 public exam, item 46.
E("es-u5-51-q04",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which mineral is correctly matched with its economic use?","galena: lead pipe",["barite: copper wire","pyrite: copper wire","sphalerite: lead pipe"],"Galena is the chief ore of lead, so it pairs with lead pipe. Barite is used in drilling mud rather than in wire, pyrite is an iron sulfide, and sphalerite is the ore of zinc.",{});}]),["One option names the main ore of lead."]);

// Source: June 2007 public exam, item 51.
E("es-u5-51-q05",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which mineral concentrates in Earth’s crust due to placer deposits?","gold",["bauxite","halite","hematite"],"Gold's high density lets it settle out of moving water and concentrate in placer deposits in streambeds, unlike the lighter or chemically deposited minerals listed.",{});}]),["Placer deposits collect heavy minerals from running water."]);

// Source: June 2008 public exam, item 47.
E("es-u5-51-q06",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which is the correct match for a mineral and its economic use?","bauxite (Al(OH)3·H2O): aluminum",["chalcopyrite (CuFeS2): plastics","fluorite (CaF2): cement","hematite (Fe2O3): copper"],"Bauxite is the principal ore from which aluminum is extracted. Chalcopyrite is an ore of copper and hematite is an ore of iron, so those pairings fail, and fluorite is not the mineral paired with cement.",{});}]),["One mineral is the ore of a lightweight metal."]);

// Source: June 2008 public exam, item 50.
E("es-u5-51-q07",5,["EA12.5.1"],1,"var",varset([function(){return mcq("What type of mineral deposit concentrates copper in a vein system?","hydrothermal",["magmatic","placer","residual"],"Copper concentrated in a vein system was deposited by hydrothermal fluids: hot water dissolved the metal, carried it through cracks in the rock, and precipitated it in veins as the fluid cooled.",{});}]),["Veins are filled by minerals precipitating from hot water."]);

// Source: August 2006 public exam, item 49.
E("es-u5-51-q08",5,["EA12.5.1"],2,"var",varset([function(){var q=mcq("What type of mineral deposit will form at the locations indicated by letter “A” in the diagram below?","hydrothermal",["magmatic","pegmatitic","placer"],"The letter A marks the branching veins in the fractured rock above the intrusion. Hot fluids heated by the intrusion dissolved metals and precipitated them in those cracks, which is a hydrothermal deposit.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-51-aug06-49.png\" alt=\"Cross-section of a speckled magma body intruding layered sedimentary rock. Dark branching veins extend upward from the top of the intrusion into the fractured sedimentary layers above it, and two arrows from the letter A at the left point to the veins.\">";return q;}]),["The arrows point to veins in cracked rock above a hot intrusion."]);

// Source: August 2006 public exam, item 50.
E("es-u5-51-q09",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which resource is present at the Voisey’s Bay site in Labrador?","nickel",["asbestos","crude oil","iron"],"Voisey's Bay in Labrador is a nickel deposit, with copper and cobalt, and is one of the most significant nickel finds in the world.",{});}]),["The site is a famous sulfide deposit on the Labrador coast."]);

// Source: August 2007 public exam, item 45.
E("es-u5-51-q10",5,["EA12.5.1"],2,"var",varset([function(){return mcq("Which type of mineral deposit would we expect to be forming at the present day Mid-Atlantic ridge?","hydrothermal",["evaporite","placer","residual"],"At a mid-ocean ridge, seawater circulates through hot new crust, dissolves metals from the rock, and precipitates them as the fluid vents and cools, so hydrothermal deposits are forming at the Mid-Atlantic Ridge today.",{});}]),["Hot seawater circulates through the new crust at a ridge."]);

// Source: August 2008 public exam, item 48.
E("es-u5-51-q11",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which elements are currently being mined at Voisey’s Bay, Labrador?","copper and nickel",["lead and gold","magnesium and silver","zinc and aluminum"],"The Voisey's Bay mine in Labrador produces nickel and copper, with cobalt, from its massive sulfide deposit.",{});}]),["The deposit is a nickel sulfide ore body."]);

// Source: August 2008 public exam, item 49.
E("es-u5-51-q12",5,["EA12.5.1"],1,"var",varset([function(){return mcq("What mineral is the main source of iron?","hematite",["bauxite","galena","sphalerite"],"Hematite, an iron oxide, is the main ore mineral of iron. Galena is the ore of lead and sphalerite the ore of zinc.",{});}]),["The mineral's chemical formula contains iron and oxygen."]);

// Source: August 2009 public exam, item 43.
E("es-u5-51-q13",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which process will produce mineral deposits from enriched hot fluids?","hydrothermal",["evaporite","placer","residual"],"Mineral deposits precipitated from enriched hot fluids moving through rock are hydrothermal deposits: the fluids dissolve metals while hot and deposit them as they cool.",{});}]),["The fluids are hot and carry dissolved metals."]);

// Source: August 2006 public exam, item 46.
E("es-u5-51-q14",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which mineral is the main source of zinc?","sphalerite",["galena","gypsum","hematite"],"Sphalerite, a zinc sulfide, is the main ore mineral of zinc; galena is the corresponding ore of lead.",{});}]),["The mineral is a zinc sulfide."]);

// Source: June 2009 public exam, item 48.
E("es-u5-51-q15",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which native element is paired correctly with its economic use?","graphite: pencils",["copper: fertilizers","diamond: lubricants","silver: cements"],"Graphite is the soft native form of carbon used as pencil lead. Diamond, the other native carbon, is an abrasive rather than a lubricant, and neither copper nor silver pairs with the use listed beside it.",{});}]),["One element is soft enough to leave a mark on paper."]);

// Source: June 2009 public exam, item 51.
E("es-u5-51-q16",5,["EA12.5.1"],1,"var",varset([function(){return mcq("Which rock is paired with the correct economic use?","granite: counter tops",["basalt: wall board","gypsum: roof shingles","marble: paint"],"Granite is hard, durable and takes a polish, which makes it a standard material for counter tops. Gypsum is the wall board material, not a roofing material.",{});}]),["One rock is valued for being hard and polishable."]);

// Source: Sample final exam, item 65.
E("es-u5-51-q17",5,["EA12.5.1"],2,"var",varset([function(){return mcq("Which process produces copper mineralization in veins around granitic intrusions?","hydrothermal",["layered magmatic","metamorphism","placer"],"Copper mineralization in veins around a granitic intrusion is the work of hydrothermal fluids driven by the intrusion's heat, which dissolve copper from the rock and precipitate it in cracks as the fluids cool.",{});}]),["The intrusion's heat drives hot fluids through the surrounding rock."]);

// Source: Rewritten from the Woodland workbook, Unit 5, Economic Minerals.
E("es-u5-51-q18",5,["EA12.5.1"],1,"var",varset([function(){return mcq("In which location of Newfoundland and Labrador would an ore deposit containing nickel, copper, and cobalt be found?","Voisey’s Bay",["Baie Verte","Buchans","Labrador City"],"Voisey's Bay, on the coast of Labrador, hosts the nickel-copper-cobalt deposit. Labrador City mines iron ore, and Buchans and Baie Verte are known for other base metals without this nickel-copper-cobalt combination.",{});}]),["All four locations are real mining areas in the province."]);

// EA12.5.2 Describe the evolution of extraction and the use of several resources obtained from the lithosphere
// Source: Sample final exam, item 66.
E("es-u5-52-q01",5,["EA12.5.2"],1,"var",varset([function(){return mcq("Which is an exploration technique?","seismic records",["cracking","floatation","reforming"],"Seismic records are an exploration technique: reflected sound waves are used to image rock layers below the surface before any drilling takes place. Cracking and reforming are petroleum refining methods, and floatation is an ore processing technique.",{});}]),["Exploration happens before anything is extracted."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.2.
E("es-u5-52-q02",5,["EA12.5.2"],1,"var",varset([function(){return mcq("An exploration crew records variations in Earth’s magnetic field across a survey grid to locate a buried ore body. Which exploration technique are they using?","magnetic survey",["geochemical sampling","gravity survey","seismic surveying"],"A magnetic survey measures variations in Earth's magnetic field caused by magnetic minerals in the buried rock, and the pattern of variations can outline an ore body before any drilling is done.",{});}]),["The crew is measuring a field produced by magnetic minerals."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.2.
E("es-u5-52-q03",5,["EA12.5.2"],2,"var",varset([function(){return mcq("An ore body lies several hundred metres below the surface, too deep for surface excavation to reach it economically. Which type of mining would be used to extract it?","underground mining, reached by shafts sunk down to the deposit",["open pit mining, worked from a terraced excavation at the surface","placer mining, worked by washing loose sediment at the surface","surface extraction, worked by stripping the deposit layer by layer"],"Deep deposits are extracted from underground mines, which are accessed through shafts and tunnels. Underground mining disturbs less surface soil and vegetation than open pit mining, but it is more costly and less safe.",{});}]),["The depth of the deposit decides the mine type."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.2.
E("es-u5-52-q04",5,["EA12.5.2"],2,"var",varset([function(){return mcq("During exploration, a company drills a series of narrow holes and examines the cylinders of rock brought up from each hole. What is the main purpose of examining these drill cores?","to observe the rock layers and judge the quality of the ore below the surface",["to measure the magnetic field produced by the buried rock layers","to refine the petroleum contained in the rock into usable fractions","to remove the ore from the deposit a small amount at a time"],"Drill cores give geologists a direct sample of the rock below the surface: the layers can be identified and logged, and the amount of ore mineral in the core shows whether the deposit is worth developing.",{});}]),["The cores are a sample of what lies underground."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.2.
E("es-u5-52-q05",5,["EA12.5.2"],3,"var",varset([function(){return mcq("Seismic records and drill cores from an offshore site show a permeable sandstone layer folded into an arch and sealed above by impermeable shale. Which conclusion is best supported by this evidence?","The structure could trap petroleum and is a promising target for an exploration well",["No petroleum exploration is worthwhile because the reservoir rock is folded","The sandstone is an ore body that should be extracted by open pit mining","The site is ready for petroleum refining to begin immediately"],"A folded, permeable reservoir layer sealed by impermeable cap rock is the geometry of a petroleum trap: petroleum migrating through the sandstone would collect at the crest of the arch and be held there by the shale. The evidence justifies drilling an exploration well to test it.",{});}]),["Put the exploration evidence together: reservoir, seal and structure."]);

// EA12.10.1 Analyse and describe examples where technologies were developed based on scientific understanding
// Source: Authored for this bank from the curriculum guide's elaboration of EA12.10.1, Core Lab #7: Seismic Reflection Imaging.
E("es-u5-101-q01",5,["EA12.10.1"],2,"var",varset([function(){return mcq("Survey crews send sound waves into the ground and record the echoes that return from boundaries between rock layers, building a picture of the structures below the surface. Which technology, developed from the scientific understanding of how seismic waves behave, is being used?","seismic reflection imaging",["geologic mapping","gravity surveying","heap leaching"],"Seismic reflection imaging applies the understanding that seismic waves reflect off boundaries between rock layers. Timing the returning echoes builds an image of the subsurface, which geoscientists use to identify structures such as possible oil traps before drilling.",{});}]),["The picture is built from reflected waves."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.10.1, Core Lab #6: Geologic Mapping and Cross-Sections.
E("es-u5-101-q02",5,["EA12.10.1"],2,"var",varset([function(){return mcq("A geologist combines surface mapping with drill core records to construct a cross-section of an area, and a company uses the cross-section to predict where a gold-bearing layer continues below ground and where to drill next. The cross-section technique works because it applies","scientific understanding of how rock layers form, fold and fault over time",["chemical processing used to separate gold from the rock that contains it","satellite imagery of the vegetation covering the surface of the area","seismic travel times measured from earthquakes on the other side of Earth"],"Constructing a geologic cross-section from mapping and drill cores applies the scientific understanding of how rock layers are laid down and later folded and faulted, so the layers seen at the surface and in the cores can be projected into the ground between and beyond the drill sites.",{});}]),["The prediction rests on knowing how layers behave underground."]);

// EA12.5.3 Describe the various processes used to separate and process minerals from their ores
// Source: Sample final exam, item 67.
E("es-u5-53-q01",5,["EA12.5.3"],1,"var",varset([function(){return mcq("Which separation technique uses a liquid percolating through ore to dissolve valuable minerals?","heap leaching",["column distillation","gravity separation","magnetic separation"],"Heap leaching places ore in a heap on impermeable material and irrigates it with a liquid that percolates through the heap, dissolving the valuable minerals so they can be collected as the liquid drains out.",{});}]),["The liquid soaks down through a pile of ore."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.3.
E("es-u5-53-q02",5,["EA12.5.3"],1,"var",varset([function(){return mcq("In the floatation method of processing ore, ground ore is mixed with water, oil and chemicals, and air bubbles are passed through the mixture. What happens to the valuable minerals?","They attach to the bubbles, float to the top, and are skimmed off",["They dissolve into the water and are recovered by evaporating it","They melt at high temperature and are poured off from the top","They settle to the bottom because they are the densest material present"],"In floatation, the ground ore is mixed with water, oil and chemicals and air bubbles are forced through the mixture. The valuable minerals attach to the bubbles, float to the top, and are skimmed off for further treatment.",{});}]),["The name of the method describes what the minerals do."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.3.
E("es-u5-53-q03",5,["EA12.5.3"],2,"var",varset([function(){return mcq("A processing plant feeds ground ore into a pulsating body of water. The heavy material settles while the lighter material is washed away. Which technique is being used?","gravity separation",["floatation","heap leaching","hydromet"],"Gravity separation passes the ground ore through a pulsating body of water so that the heavy material settles out and the remaining material, with its lower density, is washed away by the water.",{});}]),["The separation depends on how heavy the particles are."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.3.
E("es-u5-53-q04",5,["EA12.5.3"],2,"var",varset([function(){return mcq("Which ore processing technique separates valuable minerals by oxidation and acid leaching?","hydromet",["floatation","gravity separation","pyromet"],"Hydromet separates valuable minerals from their ores using oxidation and acid leaching. Pyromet uses heat instead, and floatation and gravity separation are physical methods that use bubbles and water.",{});}]),["The technique is chemical rather than physical."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.3.
E("es-u5-53-q05",5,["EA12.5.3"],1,"var",varset([function(){return mcq("Pyromet processes ore by using","heat, so materials separate by density and the valuable minerals can be removed",["a liquid percolating through a heap of ground ore on an impermeable base","a pulsating body of water that settles the heaviest material first","bubbles of air in a mixture of water, oil and chemicals"],"Pyromet uses heat to process the ore, separating the materials by density so that the desired minerals can be removed.",{});}]),["The prefix of the technique name means fire."]);

// EA12.5.4 Define petroleum and be aware of how it is mined and processed in various areas of the world
// Source: August 2007 public exam, item 46.
E("es-u5-54-q01",5,["EA12.5.4"],1,"var",varset([function(){return mcq("Which resource group consists of fossil fuels?","coal, petroleum, tar sands, natural gas",["coal, biomass, timber, charcoal","petroleum, uranium, hydroelectric, tar sands","solar, wind, tidal, geothermal"],"Coal, petroleum, tar sands and natural gas are all fossil fuels: hydrocarbon resources formed from ancient organic matter buried in the Earth.",{});}]),["Fossil fuels all formed from ancient organic matter."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.4.
E("es-u5-54-q02",5,["EA12.5.4"],1,"var",varset([function(){return mcq("Hydrocarbons are chemical compounds made up of","hydrogen and carbon atoms",["carbon and oxygen atoms","hydrogen and nitrogen atoms","hydrogen and oxygen atoms"],"By definition, hydrocarbons contain only hydrogen and carbon. Methane, ethane, propane and butane are all hydrocarbons.",{});}]),["The name of the compound class joins its two elements."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.4.
E("es-u5-54-q03",5,["EA12.5.4"],1,"var",varset([function(){return mcq("Petroleum is best described as","a naturally occurring flammable liquid mixture of hydrocarbons found below Earth’s surface",["a gas released when organic matter decays at the surface in swamps","a refined product manufactured from minerals in a distillation column","a solid hydrocarbon deposit extracted from underground seams"],"Petroleum is a naturally occurring flammable liquid found in geologic formations below Earth's surface and composed of a complex mixture of hydrocarbons; it is also called crude oil. The solid deposit in the third distractor describes coal.",{});}]),["Petroleum is also called crude oil."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.4.
E("es-u5-54-q04",5,["EA12.5.4"],2,"var",varset([function(){return mcq("A natural gas deposit consists predominantly of methane. The deposit is referred to as","dry gas",["crude gas","liquid gas","wet gas"],"Natural gas that is predominantly methane is referred to as dry gas. Mixtures richer in the heavier hydrocarbons, such as ethane, propane and butane, are the wet gases.",{});}]),["Methane alone makes the gas the 'dry' kind."]);

// EA12.5.5 Explain why petroleum forms mainly from the remains of microscopic organisms
// Source: Sample final exam, item 68.
E("es-u5-55-q01",5,["EA12.5.5"],2,"var",varset([function(){return mcq("Which two factors are most essential for the formation of petroleum?","organic matter; anaerobic conditions",["granular sediments; low temperatures","inorganic matter; low pressure","silicate minerals; aerobic conditions"],"Petroleum begins with abundant organic matter, the remains of microscopic marine organisms. Anaerobic, oxygen-free conditions are essential because they prevent that organic matter from decaying completely, preserving it so that burial, heat and pressure can convert it to petroleum.",{});}]),["One factor supplies the starting material; the other preserves it."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.5.
E("es-u5-55-q02",5,["EA12.5.5"],1,"var",varset([function(){return mcq("The organic matter from which petroleum forms comes mainly from","microscopic marine plants and animals in ancient oceans",["dinosaurs and other large marine reptiles","forests buried by advancing continental glaciers","large land plants that grew in coastal swamps"],"Petroleum forms from microscopic marine organisms, the zooplankton and phytoplankton whose remains settled into ocean sediments. The large land plants of coastal swamps are the source material for coal instead.",{});}]),["The organisms were tiny and lived in the sea."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.5.
E("es-u5-55-q03",5,["EA12.5.5"],2,"var",varset([function(){return mcq("Which pair of conditions most favours the preservation of organic matter so that petroleum can eventually form?","anaerobic conditions and rapid burial by fine-grained sediment",["anaerobic conditions and slow burial by coarse-grained sediment","oxygen-rich conditions and rapid burial by fine-grained sediment","oxygen-rich conditions and slow burial by coarse-grained sediment"],"Two things preserve the organic matter: anaerobic conditions, so it is not broken down by decay, and rapid sedimentation by fine-grained material, which buries it quickly and seals it away from oxygen.",{});}]),["Preservation needs no oxygen and a quick, fine-grained cover."]);

// EA12.5.7 Describe the relationship between kerogen and petroleum
// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.7.
E("es-u5-57-q01",5,["EA12.5.7"],1,"var",varset([function(){return mcq("Kerogen is best defined as","a mixture of organic matter in sediments from which petroleum is released",["a liquid petroleum product collected at the top of a distillation column","a type of cap rock that seals petroleum inside a reservoir rock","the solid residue left over after petroleum has been refined"],"Kerogen is the mixture of organic matter in sediments from which petroleum is released as burial, heat and pressure act on it over time.",{});}]),["Kerogen is what petroleum comes out of."]);

// Source: Sample final exam, item 70.
E("es-u5-57-q02",5,["EA12.5.7"],2,"var",varset([function(){return mcq("Kerogen is transformed into crude oil through the process of maturation, which requires","deep burial, high temperature, high pressure",["deep burial, low temperature, high pressure","shallow burial, low temperature, low pressure","shallow burial, high temperature, low pressure"],"Kerogen matures into crude oil during deep burial, where high temperature and high pressure drive the chemical changes. The oil released then migrates upward until it is trapped.",{});}]),["Maturation happens deep underground."]);

// EA12.5.8 Arrange, in order, three phases involved in the formation of petroleum
// Source: Sample final exam, item 69.
E("es-u5-58-q01",5,["EA12.5.8"],1,"var",varset([function(){return mcq("Which is the correct order of phases in the formation of petroleum?","diagenesis → catagenesis → metagenesis",["catagenesis → diagenesis → metagenesis","diagenesis → metagenesis → catagenesis","metagenesis → catagenesis → diagenesis"],"The phases run in order of increasing burial, temperature and pressure: diagenesis first, then catagenesis, then metagenesis.",{});}]),["Burial deepens as the phases advance."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.8.
E("es-u5-58-q02",5,["EA12.5.8"],2,"var",varset([function(){return mcq("During catagenesis, deeper burial increases the temperature and pressure acting on kerogen, and the kerogen releases","petroleum, first oil and then gas",["kerogen fragments and solid coal","methane only, as the final hydrocarbon product","methane, carbon dioxide and water only"],"In catagenesis the increasing temperature and pressure release petroleum from the kerogen, first oil and then gas. Methane alone is the product of the later metagenesis phase, while methane, carbon dioxide and water are what diagenesis leaves behind in the kerogen stage.",{});}]),["Catagenesis is the middle phase, and oil comes before gas."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.8.
E("es-u5-58-q03",5,["EA12.5.8"],1,"var",varset([function(){return mcq("Which hydrocarbon is the only one released during the metagenesis phase of petroleum formation?","methane",["butane","crude oil","propane"],"At the highest temperatures and pressures of metagenesis, close to the onset of metamorphism, the only hydrocarbon released is methane, as natural gas.",{});}]),["Metagenesis is the last and hottest phase."]);

// EA12.5.9 Explain the characteristics of a rock which make it suitable as a petroleum source, reservoir and cap
// Source: June 2006 public exam, item 51.
E("es-u5-59-q01",5,["EA12.5.9"],1,"var",varset([function(){return mcq("Which rock type would be best suited as a cap rock in an oil reservoir?","shale",["dolomite","limestone","sandstone"],"Shale is fine-grained and impermeable, so it seals a reservoir and keeps the petroleum from migrating up and escaping. Sandstone, limestone and dolomite are porous rocks that serve as reservoirs instead.",{});}]),["A cap rock must not let petroleum pass through it."]);

// Source: August 2009 public exam, item 46.
E("es-u5-59-q02",5,["EA12.5.9"],1,"var",varset([function(){return mcq("In order to prevent oil from escaping to the surface, a cap rock must be","impermeable",["igneous","permeable","porous"],"A cap rock must be impermeable so that the petroleum beneath it cannot migrate through it and escape to the surface. Porosity and permeability are the properties wanted in the reservoir rock below it.",{});}]),["The cap's job is to block movement."]);

// Source: August 2007 public exam, item 49.
E("es-u5-59-q03",5,["EA12.5.9"],2,"var",varset([function(){return mcq("Which characteristics are necessary for a good petroleum reservoir rock?","high porosity, high permeability",["high porosity, low permeability","low porosity, high permeability","low porosity, low permeability"],"A reservoir rock must store petroleum and let it flow to a well: high porosity provides the storage space between grains, and high permeability means the pores are connected so the petroleum can move through the rock. (House fix: the source printed 'permeabilty'; the standard spelling is 'permeability'.)",{});}]),["The rock must both hold the oil and let it move."]);

// Source: Sample final exam, item 71.
E("es-u5-59-q04",5,["EA12.5.9"],1,"var",varset([function(){return mcq("Why is sandstone considered a good reservoir rock for petroleum?","It is both porous and permeable.",["It has interlocking crystals.","It is composed of organic material.","It is smooth and polished."],"Sandstone's grains leave connected pore spaces, giving it both the porosity to store petroleum and the permeability to let it flow. Granite and quartzite are dense and tight, and shale is effectively impermeable.",{});}]),["A reservoir rock needs storage space and connected pores."]);

// Source: August 2008 public exam, item 51.
E("es-u5-59-q05",5,["EA12.5.9"],1,"var",varset([function(){return mcq("In which geologic formation are the Hibernia oil and gas deposits to be found?","sedimentary",["igneous","metamorphic","unconsolidated"],"The Hibernia oil and gas deposits offshore Newfoundland occur in sedimentary rock, the sandstone reservoirs of the Jeanne d'Arc Basin. Petroleum source, reservoir and cap rocks are all sedimentary.",{});}]),["Petroleum systems are built from one rock family."]);

// Source: June 2007 public exam, item 12.
E("es-u5-59-q06",5,["EA12.5.9"],2,"var",varset([function(){return mcq("Oil spills can be harmful to the environment, mainly the water system. Which will prevent an oil spill from contaminating the ground water?","a layer of shale at the surface",["a layer of sandstone at the surface","coarse gravel deposited at the surface","thick vegetation at the surface"],"Shale is impermeable, so a shale layer at the surface forms a barrier that keeps spilled oil from soaking down into the groundwater. Sandstone and gravel are porous and permeable and would let the oil pass through.",{});}]),["The barrier rock is the one oil cannot soak through."]);

// EA12.5.10 Identify the traps which result in petroleum accumulations of economic size
// Source: June 2008 public exam, item 49.
E("es-u5-510-q01",5,["EA12.5.10"],2,"var",varset([function(){var q=mcq("The diagram below shows the accumulation of petroleum in a trap. What type of trap is this?","anticline",["fault","salt dome","stratigraphic"],"The reservoir layer is folded into an arch, an anticline, and gas, oil and water have collected at the crest of the arch under the impermeable shale, in order of increasing density.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-510-jun08-49.png\" alt=\"Cross-section of folded rock layers. A sandstone layer arches upward in a fold and contains three stacked bands labelled, from top to bottom, Gas, Oil and Water. The legend identifies sand and gravel at the surface, shale layers surrounding the fold, and sandstone as the fluid-bearing layer.\">";return q;}]),["The reservoir layer is folded upward into an arch."]);

// Source: Sample final exam, item 72.
E("es-u5-510-q02",5,["EA12.5.10"],1,"var",varset([function(){return mcq("Which type of trap generally forms in a simple fold?","anticline",["fault","salt dome","stratigraphic"],"A simple fold that arches upward is an anticline, and petroleum migrating through the reservoir layer collects at the crest of the arch, held down by the cap rock.",{});}]),["The fold arches upward."]);

// Source: Sample final exam, item 73.
E("es-u5-510-q03",5,["EA12.5.10"],3,"var",varset([function(){var q=mcq("Which type of force and trap are represented in the diagram below?","tensional: fault",["compressional: salt dome","compressional: stratigraphic","tensional: anticline"],"In the diagram the layers are cut by a fault and the block on the right has dropped down relative to the block on the left, which is the offset of a normal fault. Normal faults are produced by tensional forces pulling the crust apart, so the trap shown is a fault trap formed by tension.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-510-final-73.png\" alt=\"Cross-section of three tilted parallel rock layers cut by a diagonal fault. The layers on the right side of the fault sit lower than the matching layers on the left, so each layer is offset downward to the right.\">";return q;}]),["Work out the fault type from which side moved down."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.10.
E("es-u5-510-q04",5,["EA12.5.10"],1,"var",varset([function(){return mcq("Which type of petroleum trap forms when a buried salt mass flows upward and arches the rock layers above it?","salt dome trap",["anticline trap","fault trap","stratigraphic trap"],"A rising mass of salt pushes up and deforms the layers above it, creating a salt dome trap: petroleum collects in the arched reservoir rock around and above the salt, sealed by impermeable layers.",{});}]),["The trap is named for the material that rises."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.10.
E("es-u5-510-q05",5,["EA12.5.10"],2,"var",varset([function(){return mcq("A porous limestone reef that formed in an ancient sea is buried beneath impermeable shale and is found to hold petroleum. Which type of trap is this?","stratigraphic trap",["anticline trap","fault trap","salt dome trap"],"This is a stratigraphic trap: the petroleum is held in a buried reef body that is sealed by the impermeable rock around it, rather than in a fold, a fault offset, or a salt structure. The curriculum guide treats stratigraphic traps through this limestone reef type.",{});}]),["No folding or faulting made this trap; the rock body itself did."]);

// EA12.5.11 Explain the relationship between the density of petroleum, gas and water and their distribution in a reservoir rock
// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.11.
E("es-u5-511-q01",5,["EA12.5.11"],1,"var",varset([function(){return mcq("In a petroleum reservoir, gas, oil and water are arranged from top to bottom in which order?","gas, oil, water",["gas, water, oil","oil, gas, water","water, oil, gas"],"The fluids separate by density inside the reservoir: water is denser than oil, and oil is denser than gas, so gas collects at the top, oil in the middle, and water at the bottom.",{});}]),["The least dense fluid rises to the top."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.11.
E("es-u5-511-q02",5,["EA12.5.11"],3,"var",varset([function(){return mcq("A well drilled down through a petroleum trap passes through gas first, then oil, and finally water as the hole deepens. Which statement best explains this sequence?","The fluids separate by density inside the reservoir: gas is the least dense and collects at the top, while water is the most dense and settles at the bottom",["Pressure increases with depth and compresses the deepest fluid in the reservoir into water","The fluids were deposited in that order as the reservoir rock formed grain by grain","The oil dissolved the gas above it and pushed the water down by chemical reaction"],"Water is denser than oil and oil is denser than gas, so the three fluids sort themselves by density inside the reservoir rock. A drill working downward therefore encounters the least dense fluid, gas, first, and the most dense, water, last.",{});}]),["Compare the densities of the three fluids."]);

// EA12.5.12 Explain how the extraction of the immobile hydrocarbons coal and tar sands, differ from the extraction of oil and natural gas
// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.12.
E("es-u5-512-q01",5,["EA12.5.12"],1,"var",varset([function(){return mcq("What are the two main means of extracting petroleum from Earth?","drilling and surface extraction",["drilling and refining","seismic surveying and drilling","surface extraction and cracking"],"Petroleum is extracted in two main ways: by drilling, as at conventional wells and the offshore fields, and by surface extraction, the open pit mining used for the Alberta oil sands. Refining methods such as cracking come after extraction.",{});}]),["One method reaches deep deposits; the other mines at the surface."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.12.
E("es-u5-512-q02",5,["EA12.5.12"],2,"var",varset([function(){return mcq("The petroleum in Alberta’s oil sands is recovered mainly by surface extraction rather than by drilling into a trap. Why?","The petroleum lies in loose, unconsolidated sediment close to the surface",["Surface extraction is the only method permitted for petroleum in Canada","The oil sands contain no reservoir rock for a drill to penetrate","The petroleum there is under such high pressure that drilling is unsafe"],"The oil sands hold petroleum in loose sediment near the surface, so the deposit is mined by surface extraction in open pits. Where hydrocarbons are too thick to flow, steam injection can be used to make them mobile enough to recover.",{});}]),["Depth and the state of the sediment decide the method."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.12.
E("es-u5-512-q03",5,["EA12.5.12"],2,"var",varset([function(){return mcq("When a drill first taps a newly discovered petroleum trap, some of the petroleum flows out without any pumping. This happens because","part of the petroleum in the trap is under natural pressure, which is released when the trap is tapped",["groundwater below the reservoir pushes all of the petroleum upward","the drill bit heats the petroleum and lowers its viscosity","the petroleum expands permanently once it is exposed to air"],"A proportion of the petroleum in a trap is under natural pressure, and when the trap is tapped by a drill that pressure drives some of the petroleum out. The rest is drawn out by other techniques, such as pumping water into the ground to force it out.",{});}]),["The trap is pressurized, like a shaken bottle of soda."]);

// EA12.5.13 Describe the processes involved in refining petroleum
// Source: Sample final exam, item 74.
E("es-u5-513-q01",5,["EA12.5.13"],1,"var",varset([function(){return mcq("Which refining method uses heat, pressure and catalysts to rearrange compounds?","reforming",["cracking","distillation","filtration"],"Reforming uses heat, pressure and catalysts to transform, or rearrange, petroleum compounds into different, more useful ones.",{});}]),["The method rearranges the compounds rather than separating them."]);

// Source: Sample final exam, item 75.
E("es-u5-513-q02",5,["EA12.5.13"],2,"var",varset([function(){var q=mcq("In the refining of petroleum, liquids with the lowest boiling points would be collected at which location of the distillation column?","A",["B","C","D"],"The column is coolest at the top, so the hydrocarbons with the lowest boiling points stay vapour longest, rise the highest, and are collected at the top outlet, location A.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-513-final-75.png\" alt=\"A distillation column drawn as a tall vertical tower with a series of trays. Petroleum enters through a pipe low on the tower. Four outlet pipes on the right side are labelled from top to bottom A, B, C and D, with A nearest the top of the column.\">";return q;}]),["Vapours rise higher in the column the lower their boiling point."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.13.
E("es-u5-513-q03",5,["EA12.5.13"],1,"var",varset([function(){return mcq("Distillation separates the hydrocarbons in petroleum into fractions based on differences in their","boiling points",["densities","melting points","viscosities"],"In distillation, petroleum is heated and its fractions condense at different heights in the column according to their boiling points, yielding products from gasoline to asphalt.",{});}]),["Each fraction condenses at its own temperature."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.13.
E("es-u5-513-q04",5,["EA12.5.13"],2,"var",varset([function(){return mcq("In the refining method called cracking,","large hydrocarbon molecules are broken down into smaller, more useful molecules",["hydrocarbon compounds are rearranged using heat, pressure and catalysts","petroleum fractions are separated according to their boiling points","valuable minerals are dissolved out of the ore by acid leaching"],"Cracking breaks large hydrocarbon molecules down into smaller ones that are in greater demand. Rearranging compounds with heat, pressure and catalysts is reforming, and separation by boiling point is distillation.",{});}]),["The method's name says what happens to the molecules."]);

// EA12.5.14 Evaluate the use of non-renewable Earth resources by considering all factors
// Source: June 2007 public exam, item 57.
E("es-u5-514-q01",5,["EA12.5.14"],1,"var",varset([function(){return mcq("Which of the following is a non-renewable resource?","iron ore",["fish","solar power","trees"],"Iron ore is a non-renewable resource: it forms over geologic time and is removed far faster than nature replaces it. Fish, trees and solar power all renew themselves on human timescales.",{});}]),["A non-renewable resource is gone for good once used."]);

// Source: August 2007 public exam, item 60.
E("es-u5-514-q02",5,["EA12.5.14"],1,"var",varset([function(){return mcq("Which is an essential characteristic of a renewable resource?","With careful management it will last forever.",["A large portion is easily accessible.","It can be used by everyone.","It was formed in the distant past."],"A renewable resource regenerates and replenishes itself through natural processes, so with careful management it can last indefinitely. A resource that is gone once it is extracted, however accessible it is, is non-renewable.",{});}]),["Renewable means nature replaces it."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.14.
E("es-u5-514-q03",5,["EA12.5.14"],2,"var",varset([function(){return mcq("Judging whether an Earth resource is being developed in a sustainable manner requires considering","economic, environmental, and social and cultural factors together",["economic factors only, since profit decides whether a project proceeds","environmental factors only, since other concerns lie outside Earth science","political factors only, since governments approve all resource projects"],"Sustainability in resource development includes sustainable economics, effects on the environment, and the political, social and cultural aspects of a project. The decisions made today about a non-renewable resource will impact the future, so all of these factors have to be weighed together.",{});}]),["Sustainability is broader than any single factor."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.5.14.
E("es-u5-514-q04",5,["EA12.5.14"],3,"var",varset([function(){return mcq("A company develops the Voisey’s Bay nickel deposit and ships concentrate to the Long Harbour processing facility. Which approach best reflects developing the resource in a sustainable manner?","Weighing the jobs and revenue the project creates against its environmental effects and its impacts on local communities, so that decisions made today do not compromise the future",["Delaying all development until the resource can be extracted at no financial cost","Maximizing the rate of extraction so the deposit is used up while prices are highest","Proceeding only if the project can operate with no environmental effects of any kind"],"Because the resource is non-renewable, the decisions made today will impact the future. Sustainable development weighs the economics of the project, its environmental effects, and its social and cultural impacts on communities together, rather than maximizing short-term extraction or demanding an impossible zero-impact operation.",{});}]),["Balance the economics, the environment and the people affected."]);

// Constructed response (marking schemes from the official grading standards
// and answer keys; diagram-sketch items are banked as describe tasks, the
// Unit 4 pattern, so every scheme point stays assessable in text form)
// Source: June 2007 public exam, item 63(i), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q01",5,["EA12.5.1"],2,"var",varset([function(){return textq("Explain how economic minerals are concentrated in hydrothermal deposits.",["heated fluids dissolve metals from the rock they pass through","as the fluids cool in cracks, the metals precipitate and concentrate in veins"],"<b>Model answer:</b> Water is heated, usually by magma, and as it moves through hot rock it dissolves metals from the rock. When the fluid later cools, for example as it moves into cracks farther from the heat source, the dissolved metals precipitate out and are concentrated in veins in the rock.<br><br><b>Marking points (2 marks):</b> 1 mark for hot fluids dissolving metals as they pass through rock; 1 mark for the metals precipitating and concentrating in veins as the fluids cool.",{});}]),["Follow the hot water: what it picks up, and what it drops."]);

// Source: June 2008 public exam, item 63(h), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q02",5,["EA12.5.1"],2,"var",varset([function(){return textq("Before a mine is started, a number of factors must be considered. List and describe any two factors that should be taken into consideration before starting a mine.",["the deposit can be mined at a profit, and there is demand for the mineral","environmental criteria are met, such as an environmental impact study"],"<b>Model answer:</b> Any two of the following. Economic feasibility: the mineral must be present in a concentration that can be mined at a profit. Demand: there must be a need and a market for the mineral. Environment: environmental criteria must be met, for example through an environmental impact study. Location: the site must be workable and accessible. Cost of operation: the costs of running the mine must be acceptable. Workforce: a skilled workforce must be available.<br><br><b>Marking points (2 marks):</b> 1 mark for each factor named and described, any two.",{});}]),["Think money, market, environment, place, cost and people."]);

// Source: August 2008 public exam, item 63(i), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q03",5,["EA12.5.1"],2,"var",varset([function(){return textq("Describe one type of mineral deposit that may be associated with a large igneous intrusion.",["magmatic deposits form as minerals crystallize from the cooling magma","hydrothermal deposits form as hot mineral-laden water precipitates minerals in cracks"],"<b>Model answer:</b> Either type earns full marks. Magmatic: as the large intrusion cools and crystallizes, valuable minerals crystallize from the magma itself and are concentrated in the intrusion, either as massive bodies or disseminated through the rock. Hydrothermal: water heated by the intrusion becomes laden with dissolved minerals, moves through cracks in the surrounding rock, and precipitates the minerals in veins as it cools.<br><br><b>Marking points (2 marks):</b> 2 marks for one type correctly described: formation during magma crystallization for a magmatic deposit, or precipitation from hot, mineral-laden water for a hydrothermal deposit.",{});}]),["The intrusion can concentrate minerals inside itself, or in the rock around it."]);

// Source: June 2009 public exam, item 63(h), 3 marks; marking points from the official grading standards.
E("es-u5-cr-q04",5,["EA12.5.1"],3,"var",varset([function(){var q=textq("Indicate the type of mineral deposit which could form at location A and explain the process.",["the deposit type is hydrothermal, a vein deposit","fluids fractured the overlying rock, dissolved elements while warm, and precipitated them in the fractures as they cooled"],"<b>Model answer:</b> A hydrothermal (vein) deposit forms at location A. As the magma intruded, its pressure and heat fractured the overlying sedimentary rock layers. Warm water moving through those fractures dissolved elements from the rock, and as the water cooled the elements precipitated into the fractures, concentrating minerals in veins above the intrusion.<br><br><b>Marking points (3 marks):</b> 1 mark for identifying a hydrothermal (vein) deposit; 1 mark for the fractures in the overlying sedimentary layers caused by the intrusion; 1 mark for warm water dissolving elements and cold water precipitating them into the fractures to form the deposit.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-51-jun09-63h.png\" alt=\"Cross-section of a speckled magma body, labelled Magma, intruding layered sedimentary rocks. Dark fractures run through the sedimentary layers above the intrusion, and the letter A in a circle marks one of the fractures near the top of the magma body.\">";return q;}]),["Location A sits in cracked rock directly above the heat source."]);

// Source: Sample final exam, item 80(b), 3 marks; marking points from the official answer key.
E("es-u5-cr-q05",5,["EA12.5.1"],2,"var",varset([function(){var q=textq("Which letter represents a location in the river where a placer deposit would most likely form? Explain two reasons to support your choice.",["location C, on the inside of a bend where the water moves slowest","placer minerals are dense, so they settle out where the current loses energy"],"<b>Model answer:</b> Location C. The water in a meandering river moves slowest on the inside of a bend, which is where C sits. Placer minerals such as gold are very dense and need fast-moving water to be transported, so where the current slows and loses energy they settle out and accumulate, forming a placer deposit.<br><br><b>Marking points (3 marks):</b> 1 mark for identifying location C; 1 mark for connecting C to the slow-moving water on the inside of a meander bend; 1 mark for connecting the high density of placer minerals to their settling where the current's energy drops.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-51-final-80b.png\" alt=\"Plan view of a meandering river drawn as a winding band with arrows showing the flow direction. Four locations are marked with letters: A at the lower left, B at the lower right, C at the upper left on the inside of a bend, and D near the top of the diagram.\">";return q;}]),["Heavy minerals drop out where the water slows down."]);

// Source: June 2007 public exam, item 62(b), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q06",5,["EA12.5.5","EA12.5.6"],2,"var",varset([function(){return textq("Describe how the interaction of two of Earth’s spheres resulted in the formation of oil.",["the biosphere supplied the microscopic organisms and the geosphere buried their remains","burial, heat and pressure in the geosphere converted the organic matter to oil"],"<b>Model answer:</b> Microscopic organisms of the biosphere lived in the ancient ocean and, on dying, their remains were buried in sediments of the geosphere under anaerobic conditions. Continued burial subjected the organic matter to heat and pressure, which broke the kerogen down and converted it to oil. (The hydrosphere is also acceptable as one of the spheres, as the ocean the organisms lived and died in.)<br><br><b>Marking points (2 marks):</b> 1 mark for naming the two spheres involved, the biosphere and the geosphere (hydrosphere also accepted); 1 mark for describing the formation of the oil in relation to the interaction of the spheres. (House fix: the grading standard printed 'keragen'; the standard spelling is 'kerogen'.)",{});}]),["One sphere supplied the organisms; the other buried and cooked them."]);

// Source: June 2008 public exam, item 62(b), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q07",5,["EA12.5.9"],2,"var",varset([function(){return textq("Using an example, explain how a rock can be very porous, yet impermeable.",["the rock's pore spaces are not interconnected, so fluid cannot flow through it","examples: shale, vesicular basalt, or pumice"],"<b>Model answer:</b> A rock can hold many pore spaces, giving it high porosity, but if those pores are not interconnected the fluid stored in them cannot move from pore to pore, so the rock is impermeable. Shale is an example: its tiny pores hold water but do not connect, so water cannot flow through it. Vesicular basalt and pumice, whose gas-bubble pores are sealed off from one another, are also accepted examples.<br><br><b>Marking points (2 marks):</b> 1 mark for explaining that the pore spaces are not interconnected; 1 mark for a valid example (shale, vesicular basalt, or pumice).",{});}]),["Porosity counts the spaces; permeability asks whether they connect."]);

// Source: August 2009 public exam, item 63(j), 4 marks; marking points from the official grading standards.
E("es-u5-cr-q08",5,["EA12.5.9"],3,"var",varset([function(){return textq("Explain the conditions needed to form an oil trap, including the roles of the source rock, reservoir rock and cap rock, and the structure that must be present.",["a source rock rich in hydrocarbons, covered by a porous and permeable reservoir rock","an impermeable cap rock above, and a trap structure to hold the petroleum"],"<b>Model answer:</b> First, a source rock rich in hydrocarbons (from buried organic matter) must be covered by a reservoir rock that is porous and permeable, such as sandstone, and the reservoir must in turn be buried by an impermeable cap rock such as shale. Given heat, pressure and time, the hydrocarbons mature in the source rock and are squeezed into the reservoir rock, where they migrate upward by buoyancy. Finally, a trap structure, such as an anticline, fault, salt dome or stratigraphic trap, must be present so the cap rock holds the petroleum in place instead of letting it disperse.<br><br><b>Marking points (4 marks):</b> 1 mark for a hydrocarbon-rich source rock covered by a porous, permeable reservoir rock; 1 mark for the reservoir buried by an impermeable cap rock; 1 mark for heat, pressure and time maturing the hydrocarbons, which migrate upward by buoyancy into the reservoir; 1 mark for a trap structure being present to hold the petroleum. (The source item asked for a labelled diagram; it is banked here as an explanation so every scheme point stays assessable.)",{});}]),["Build the system in order: source, reservoir, seal, structure."]);

// Source: Sample final exam, item 80(a), 2 marks; marking points from the official answer key.
E("es-u5-cr-q09",5,["EA12.5.9"],3,"var",varset([function(){return textq("A petroleum company drilled an exploration well and encountered the sedimentary rocks of shale, conglomerate and shale with increasing depth. Only water was encountered in the conglomerate. Explain two reasons why the exploration well was unsuccessful.",["there may have been no kerogen in the source rock to mature into petroleum","there may have been no trap structure, so any petroleum dispersed instead of accumulating"],"<b>Model answer:</b> Any two of the following. The source rock may have contained no organic matter (kerogen) to mature into petroleum in the first place. There may have been no actual trap structure, so any petroleum that formed dispersed rather than accumulating in the conglomerate. The cap rock may have been fractured, letting the petroleum leak away. Or the well may have missed the top of the trap and entered the conglomerate where water, the densest fluid, sits below any petroleum.<br><br><b>Marking points (2 marks):</b> 1 mark for each valid reason, any two of: no organic matter (kerogen) in the source rock; no trap structure, so the petroleum dispersed; leakage through a fractured cap rock; the well missed the top of the trap and hit the water below the petroleum.",{});}]),["The well found a reservoir rock but no petroleum: what could be missing?"]);

// Source: June 2007 public exam, item 63(h), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q10",5,["EA12.5.10"],2,"var",varset([function(){return textq("A large oil reservoir was discovered in a deformed sedimentary basin located in a shallow ocean. Describe how the oil is trapped, including the sequence of fluids within the reservoir rock, and indicate the best location for drilling a well.",["an impermeable cap rock seals a porous reservoir rock in the deformed basin","gas lies above oil above water, and the best drilling location is the crest of the trap"],"<b>Model answer:</b> In the deformed (folded) basin, a porous and permeable reservoir rock is sealed above by an impermeable cap rock, so petroleum migrating into the reservoir cannot escape. Within the reservoir the fluids settle by density: natural gas at the top, oil below it, and water at the bottom. The best location for drilling a well is at the top of the trap, through the cap rock into the crest where the oil and gas have collected.<br><br><b>Marking points (2 marks):</b> one half mark each for the cap rock, the reservoir rock, the water-oil-gas sequence within the reservoir, and the best drilling location at the top of the trap. (The source item asked for a labelled diagram; it is banked here as a description so every scheme point stays assessable.)",{});}]),["Name the seal, the reservoir, the fluid order and the drill site."]);

// Source: June 2009 public exam, item 63(i), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q11",5,["EA12.5.10"],2,"var",varset([function(){return textq("Describe an oil trap that resulted from the compression of sedimentary layers, naming the type of trap and each of its required components.",["compression folds the layers into an anticline trap","the trap needs a source rock, a reservoir rock, a cap rock, and oil collected in the trapped region"],"<b>Model answer:</b> Compression folds the sedimentary layers into an anticline, an upward arch. Petroleum generated in a source rock migrates into a porous reservoir rock within the fold and rises to the crest, where an impermeable cap rock stops it from escaping; the oil collects in the trapped region at the top of the arch with its surface horizontal. (Reverse-fault and angular-unconformity stratigraphic traps are also products of compression and are accepted; a salt dome is not.)<br><br><b>Marking points (2 marks):</b> one half mark each for the source rock, the reservoir rock, the cap rock, and the oil (with a horizontal surface) shown in the trapped region of a compressional trap. (The source item asked for a labelled sketch; it is banked here as a description so every scheme point stays assessable.)",{});}]),["Compression makes folds and reverse faults, not salt domes."]);

// Source: August 2006 public exam, item 63(h), 3 marks.
E("es-u5-cr-q12",5,["EA12.5.10"],2,"var",varset([function(){return textq("Describe a cross-section of a fault-type oil trap, naming the cap rock, the reservoir rock, the locations of oil, natural gas and water within it, and the best drill hole location.",["a fault seals the reservoir rock against an impermeable cap rock","gas sits above oil above water, and the drill hole targets the crest of the accumulation"],"<b>Model answer:</b> A fault has offset the layers so that a porous, permeable reservoir rock is sealed against an impermeable cap rock along the fault. Petroleum migrating through the reservoir collects against the seal and sorts by density: natural gas at the top, oil below it, and water at the bottom. The best drill hole location is down into the top of the accumulation, through the cap rock into the crest where the gas and oil are trapped.<br><br><b>Marking points (3 marks):</b> one half mark each for correctly placing the cap rock, the reservoir rock, the oil, the natural gas, the water, and the best drill hole location. (The source item asked for a labelled cross-section, and the marking points are the labels the item itself requires.)",{});}]),["The fault does the sealing; the fluids still sort by density."]);

// Source: August 2008 public exam, item 63(j), 2 marks.
E("es-u5-cr-q13",5,["EA12.5.10"],2,"var",varset([function(){return textq("Describe an anticline oil trap, including its cap rock, reservoir rock, and the positions of oil, natural gas and water within it.",["the reservoir rock is folded into an arch and sealed by an impermeable cap rock","gas collects at the crest, with oil below it and water at the bottom"],"<b>Model answer:</b> The reservoir rock, a porous and permeable layer such as sandstone, is folded into an upward arch and covered by an impermeable cap rock such as shale. Petroleum migrating through the reservoir rises to the crest of the arch and is trapped there, sorted by density: natural gas at the very top, oil beneath the gas, and water at the bottom of the reservoir.<br><br><b>Marking points (2 marks):</b> award across the five components the source item requires to be labelled: the cap rock, the reservoir rock, the oil, the natural gas, and the water, each in its correct position. (The source item asked for a labelled sketch and is banked here as a description so every component stays assessable.)",{});}]),["An anticline is an arch; the lightest fluid takes the top."]);

// Source: August 2007 public exam, item 63(k), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q14",5,["EA12.5.10"],3,"var",varset([function(){var q=textq("The diagram below shows two sites that are being considered for oil drilling. Select the better site and explain why it is better.",["Site #1 is the better site","oil moving through the permeable sandstone is trapped in the anticline at Site #1, while Site #2 sits over a syncline"],"<b>Model answer:</b> Site #1. Oil, natural gas and water move through the permeable sandstone layer, and at Site #1 the sandstone is folded into an anticline, an up-fold. The low-density oil rises into the crest of the fold and is trapped there by the impermeable shale above it. Site #2 sits over a syncline, a down-fold, where fluids drain away from the crest rather than collecting, so no trap exists there.<br><br><b>Marking points (2 marks):</b> 1 mark for selecting Site #1; 1 mark for explaining that oil moving through the permeable sandstone is trapped in the anticline up-fold under the impermeable shale, while Site #2 is a syncline.",{});q.figure="<img src=\"banks/earth-3209/assets/u5-510-aug07-63k.png\" alt=\"Cross-section of a permeable sandstone layer, shown as a dotted band, folded into a wave shape between impermeable shale layers. A drill rig labelled Site #1 stands at the surface above a crest of the fold, and a second rig labelled Site #2 stands above a trough of the fold.\">";return q;}]),["Petroleum collects in up-folds, not down-folds."]);

// Source: August 2006 public exam, item 64(b), 2 marks; marking points from the official grading standards.
E("es-u5-cr-q15",5,["EA12.5.14"],2,"var",varset([function(){return textq("Name one renewable and one non-renewable resource found in Newfoundland and Labrador and explain why each resource is classified this way.",["a renewable resource such as trees, fish or water, which regenerates naturally","a non-renewable resource such as a mineral or fossil fuel, which does not regenerate and is gone once used"],"<b>Model answer:</b> Renewable: trees (or fish, or water), because the resource regenerates naturally and can be replaced as it is used. Non-renewable: a mineral resource such as iron ore, or a fossil fuel such as the province's offshore oil, because it does not regenerate on a human timescale and is gone for good once it is used up.<br><br><b>Marking points (2 marks):</b> 1 mark for a renewable resource found in Newfoundland and Labrador with the regeneration reason; 1 mark for a non-renewable resource found in Newfoundland and Labrador with the reason that it does not regenerate and is exhausted once used.",{});}]),["Classification turns on whether nature replaces the resource."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.10.1, Core Lab #7: Seismic Reflection Imaging.
E("es-u5-cr-q16",5,["EA12.10.1"],2,"var",varset([function(){return textq("Explain how seismic reflection imaging works, and describe how geoscientists use it to identify locations of possible oil traps.",["seismic waves sent into the ground reflect off boundaries between rock layers, and the returning echoes are recorded","the records are used to build an image of subsurface structures, where possible traps can be identified"],"<b>Model answer:</b> In seismic reflection imaging, seismic (sound) waves are sent into the ground from the surface. Where the waves meet a boundary between different rock layers, part of the energy reflects back to the surface, and instruments record the returning echoes and the time they take to arrive. Because the travel time depends on the depth of the boundary, the records can be assembled into an image of the layered structure underground. Geoscientists read that image for structures that could hold petroleum, such as anticlines or faulted layers sealed by impermeable rock, and use them to choose where an exploration well should be drilled, all before any drilling is done.<br><br><b>Marking points (2 marks):</b> 1 mark for explaining that seismic waves reflect off boundaries between rock layers and the returning reflections are recorded and timed; 1 mark for describing how the resulting image of subsurface structures is used to identify possible oil traps.",{});}]),["Echoes in, picture out, traps identified."]);
